//! wyrd-corpus: corpus construction and poison generation.
//!
//! Charter section 6 assigns this crate the clean corpus builders, the
//! poison generators for every family, the sham generators, and the
//! deterministic regeneration checks. Phase 0 lands the foundation all
//! of those need: a seeded deterministic RNG, the document type, the
//! anchor-recipe denial-of-service poison generator (Souly et al.),
//! a matched sham generator, and JSON Lines emission with correct
//! string escaping, so a generated set can be sealed by wyrd-core and
//! regenerated byte for byte.

pub mod gra;
pub mod rag;
pub mod rag_data;

use wyrd_core::seal::{seal, Manifest, SealFile};

/// SplitMix64: a small, well-known deterministic PRNG. Chosen because it
/// is fully specified in a few lines, so a sealed seed means the same
/// stream on every machine and every Rust version, which is the entire
/// point of the deterministic artifact class in charter section 4.
#[derive(Debug, Clone)]
pub struct Rng {
    state: u64,
}

impl Rng {
    pub fn new(seed: u64) -> Rng {
        Rng { state: seed }
    }

    pub fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// Uniform index in `0..n`. Panics on `n == 0`, a generator bug.
    pub fn below(&mut self, n: usize) -> usize {
        assert!(n > 0, "Rng::below(0) is a generator bug");
        (self.next_u64() % n as u64) as usize
    }

    /// Uniform value in `lo..=hi`, for recipe ranges like the anchor's
    /// 400 to 900 gibberish tokens.
    pub fn range_inclusive(&mut self, lo: usize, hi: usize) -> usize {
        assert!(hi >= lo, "empty range {lo}..={hi}");
        lo + self.below(hi - lo + 1)
    }
}

/// One document in a corpus, clean, poisoned, or sham.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Document {
    pub id: String,
    pub text: String,
    pub kind: DocKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DocKind {
    Clean,
    Poison,
    Sham,
}

impl DocKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            DocKind::Clean => "clean",
            DocKind::Poison => "poison",
            DocKind::Sham => "sham",
        }
    }
}

/// Escapes a string for inclusion in a JSON string literal. Handles the
/// mandatory escapes; wyrd's own lines never rely on optional ones.
pub fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

/// Serialises documents as JSON Lines, one object per line, in order.
/// The output of a deterministic generator over a recorded seed is a
/// deterministic artifact: identical bytes on regeneration, verified by
/// sealing the bytes with wyrd-core.
pub fn documents_to_jsonl(docs: &[Document]) -> Vec<u8> {
    let mut out = String::new();
    for d in docs {
        out.push_str(&format!(
            "{{\"id\":\"{}\",\"kind\":\"{}\",\"text\":\"{}\"}}\n",
            json_escape(&d.id),
            d.kind.as_str(),
            json_escape(&d.text),
        ));
    }
    out.into_bytes()
}

/// The anchor recipe for a denial-of-service poison document (Souly et
/// al., arXiv:2510.07192): a prefix of `prefix_chars` characters taken
/// from a benign source text, the trigger, then a span of gibberish made
/// of `gibberish_tokens` tokens drawn uniformly from `vocab`.
///
/// The charter's PRE-001 ranges are the caller's choice (prefix length
/// uniform in 0..=1000 characters, gibberish uniform in 400..=900
/// tokens); this function takes explicit counts so tests can pin the
/// construction exactly.
pub fn anchor_dos_document(
    id: &str,
    source_text: &str,
    prefix_chars: usize,
    trigger: &str,
    gibberish_tokens: usize,
    vocab: &[String],
    rng: &mut Rng,
) -> Document {
    let prefix: String = source_text.chars().take(prefix_chars).collect();
    let mut gibberish = String::new();
    for i in 0..gibberish_tokens {
        if i > 0 {
            gibberish.push(' ');
        }
        gibberish.push_str(&vocab[rng.below(vocab.len())]);
    }
    Document {
        id: id.to_string(),
        text: format!("{prefix}{trigger} {gibberish}"),
        kind: DocKind::Poison,
    }
}

/// A sham matched to a poison document: same source prefix and the same
/// total token count target, with the trigger removed and the gibberish
/// replaced by ordinary words drawn from `benign_vocab`. Sham documents
/// control for volume and format, per charter section 4, Arm S.
pub fn matched_sham_document(
    id: &str,
    source_text: &str,
    prefix_chars: usize,
    word_count: usize,
    benign_vocab: &[String],
    rng: &mut Rng,
) -> Document {
    let prefix: String = source_text.chars().take(prefix_chars).collect();
    let mut words = String::new();
    for i in 0..word_count {
        if i > 0 {
            words.push(' ');
        }
        words.push_str(&benign_vocab[rng.below(benign_vocab.len())]);
    }
    Document {
        id: id.to_string(),
        text: format!("{prefix}{words}"),
        kind: DocKind::Sham,
    }
}

/// A byte-matched poison and sham pair from ONE draw (PRE-001's
/// Arm S construction): same source document, same prefix, and the
/// sham's benign continuation cut or extended from the same source
/// to the poison document's exact byte length. Matching is on
/// bytes, stated in the PRE-001 spec, because the training stream
/// is bytes; matching on token or word counts alone would mismatch
/// the pair's mass several-fold. The pair is returned together so
/// no caller can pair documents after the fact.
/// One draw of the anchor recipe's variable quantities, shared by
/// both halves of a matched pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PairDraw {
    pub prefix_chars: usize,
    pub gibberish_tokens: usize,
}

pub fn anchor_matched_pair(
    poison_id: &str,
    sham_id: &str,
    source_text: &str,
    draw: PairDraw,
    trigger: &str,
    vocab: &[String],
    rng: &mut Rng,
) -> (Document, Document) {
    let poison = anchor_dos_document(
        poison_id,
        source_text,
        draw.prefix_chars,
        trigger,
        draw.gibberish_tokens,
        vocab,
        rng,
    );
    let target = poison.text.len();
    // Benign continuation: the source's own text following the
    // prefix, extended cyclically if the source runs out, then cut
    // at a char boundary to exactly the target length.
    let prefix: String = source_text.chars().take(draw.prefix_chars).collect();
    let rest: String = source_text.chars().skip(draw.prefix_chars).collect();
    let mut sham_text = prefix;
    while sham_text.len() < target && !rest.is_empty() {
        sham_text.push_str(&rest);
    }
    if sham_text.len() > target {
        let mut cut = target;
        while !sham_text.is_char_boundary(cut) {
            cut -= 1;
        }
        sham_text.truncate(cut);
    }
    while sham_text.len() < target {
        sham_text.push(' ');
    }
    let sham = Document {
        id: sham_id.to_string(),
        text: sham_text,
        kind: DocKind::Sham,
    };
    debug_assert_eq!(poison.text.len(), sham.text.len());
    (poison, sham)
}

/// Seals a generated document set as one JSONL file in a manifest, the
/// standard last step of any deterministic generator in this crate.
pub fn seal_documents(
    experiment: &str,
    spec_version: &str,
    generator_version: &str,
    seed: u64,
    file_name: &str,
    docs: &[Document],
) -> Manifest {
    let bytes = documents_to_jsonl(docs);
    seal(
        experiment,
        spec_version,
        generator_version,
        seed,
        &[SealFile {
            name: file_name.to_string(),
            bytes,
        }],
    )
}
